={
  "success": true,
  "cpf": "{{ $('Parse e-SAJ Response').item.json.cpf }}",
  "nome": "{{ $('Parse e-SAJ Response').item.json.nome_extraido }}",
  "total_processos": {{ $('Parse e-SAJ Response').item.json.total_processos }},
  "processos": {{ JSON.stringify($('Parse e-SAJ Response').item.json.processos_array, null, 2) }},
  "resposta": "{{ $('Parse e-SAJ Response').item.json.responseText.replace(/"/g, '\\"').replace(/\n/g, '\\n') }}",
  "status_pagamento": "PAYMENT_APPROVED",
  "inserted_id": {{ $json.id || 0 }}
}
